INSERT INTO `location` VALUES (18,'广西大学东27栋B区','','生活','',1,'/uploads/e228cca837314e509bc5067fa566b30e.jpg',22.855539713639548,108.28997254371644,'东27栋B区','全天','3235110',1),(19,'广西大学第六教学楼','','教学','广西大学第六教学楼为学校重点建设工程，是广西大学实施“中西部高校提升综合实力计划”的重要项目。建成的教学大楼位于东校园教学中心区，北濒碧云湖，西邻东十教，东面艺术学院，南向哺育园广场。占地面积6127.01㎡，总建筑面积：37612.99㎡，建筑高度为23.995m，抗震设防烈度为6度。地下一层主要功能为地下停车车库以及设备用房、室外下沉庭院、超大型350座多功能阶梯教室；地上六层主要功能为教室以及教室休息室等配套用房，设计座位容量14540个（实际容量近15000个）；地下机动车停车位72个，地下非机动车面积1011.87㎡。项目主体工程于2014年1月25日开工建设，历时整整两年1个月的时间投入使用',NULL,'',22.84604835787595,108.29097032546997,'第六教学楼','周一至周日7：00—22：30，考试日暂定','',2),(20,'广西大学附属中学','','教学','',NULL,'',22.847497809843627,108.28592777252199,'西大附中','','',3),(21,'位于南大门','','生活','西大经典地标，背景是棕榈树与教学楼。',NULL,'',22.83830399811554,108.28453838825226,'育才广场','全天','',4),(22,'广西大学劝学岛','','教学','月牙湖三面环绕，岛内一组典雅仿古筑错落其间，知行书院、六角亭、连理水榭彼此呼应，曲水流觞蜿蜒而过。',NULL,'/uploads/57506c36fa9248b4a00e230bf343c7cf.png,/uploads/20e560f7c24746798c11a87bfbf8ac04.png',22.84740487138956,108.28917860984804,'劝学岛','全天','',5),(23,'广西大学老水塔','','餐饮','用红砖砌成圆柱形塔身，其高大形象和独特的建筑风格，为校园注入了独特的文化气息。',1,'',22.84754131295364,108.2905411720276,'老水塔','','',6),(24,'大学生活动中心','','服务','紧邻碧云湖畔，内部造型灵动，室内、学生社团活动、学术讲座常汇聚于此。',1,'',22.84738509723739,108.29109370708467,'大学生活动中心','','',7),(25,'广西大学碧云湖','','生活','有湖心岛、爱国民主运动纪念碑，夕阳时分水天相映，柳烟垂拂，是绝佳取景地。',1,'',22.846463618549606,108.29254746437074,'碧云湖','全天','',8),(26,'广西大学雁归园','','生活','位于校园北部，紧邻雁归湖，得名于西大文脉源头桂林雁山园，承载“雁归思源”的文化寓意。',1,'',22.854036959793767,108.28246235847475,'雁归园','全天','',9),(27,'广西大学西体育场','','运动','运动运动',1,'',22.843902824195887,108.28532695770265,'西体育场','','',10);
/*!40000 ALTER TABLE `location` ENABLE KEYS */;
